// Renders charts from results.js (generated by run_experiments.py). No libraries needed.
(function () {
  const R = window.QSP_RESULTS;
  const $ = (id) => document.getElementById(id);
  const NS = "http://www.w3.org/2000/svg";
  const pct = (x, d = 1) => (100 * x).toFixed(d) + "%";
  const pp = (x) => (x >= 0.01 ? pct(x, 1) : "1 in " + Math.round(1 / x).toLocaleString());
  let cur = R.sizes[0], view = "stocks";

  function el(tag, attrs, text) {
    const e = document.createElementNS(NS, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (text != null) e.textContent = text;
    return e;
  }
  const css = (v) => getComputedStyle(document.documentElement).getPropertyValue(v).trim();

  // ---------- scatter: risk (x) vs profit (y) ----------
  function scatter(svg, pts, opts) {
    svg.innerHTML = "";
    const W = 640, H = 420, m = { l: 58, r: 20, t: 14, b: 48 };
    const all = pts.concat(opts.extra || []);
    const xs = all.map((p) => p.risk), ys = all.map((p) => p.profit);
    const pad = (a, b) => (b - a) * 0.08 || 0.01;
    const x0 = Math.min(...xs) - pad(Math.min(...xs), Math.max(...xs)), x1 = Math.max(...xs) + pad(Math.min(...xs), Math.max(...xs));
    const y0 = Math.min(...ys) - pad(Math.min(...ys), Math.max(...ys)), y1 = Math.max(...ys) + pad(Math.min(...ys), Math.max(...ys));
    const X = (v) => m.l + ((v - x0) / (x1 - x0)) * (W - m.l - m.r);
    const Y = (v) => H - m.b - ((v - y0) / (y1 - y0)) * (H - m.t - m.b);
    const ticks = (a, b) => {
      const step = [0.01, 0.02, 0.05, 0.1].find((t) => (b - a) / t <= 7) || 0.1, out = [];
      for (let v = Math.ceil(a / step - 1e-9) * step; v <= b + 1e-9; v += step) out.push(v);
      return out;
    };
    ticks(x0, x1).forEach((xv) => {
      svg.append(el("line", { x1: X(xv), x2: X(xv), y1: m.t, y2: H - m.b, stroke: css("--grid") }));
      svg.append(el("text", { x: X(xv), y: H - m.b + 18, "text-anchor": "middle" }, pct(xv, 0)));
    });
    ticks(y0, y1).forEach((yv) => {
      svg.append(el("line", { x1: m.l, x2: W - m.r, y1: Y(yv), y2: Y(yv), stroke: css("--grid") }));
      svg.append(el("text", { x: m.l - 8, y: Y(yv) + 4, "text-anchor": "end" }, pct(yv, 0)));
    });
    svg.append(el("text", { x: (W + m.l) / 2, y: H - 8, "text-anchor": "middle" }, "Risk (volatility per year) →  lower is better to the left"));
    const yl = el("text", { x: 14, y: H / 2, "text-anchor": "middle", transform: `rotate(-90 14 ${H / 2})` }, "Profit (expected return per year) → higher is better");
    svg.append(yl);
    opts.draw(svg, X, Y);
  }

  function drawStocks(svg) {
    const q = new Set(cur.qaoa.picked), b = new Set(cur.brute.picked);
    scatter(svg, cur.stocks, {
      draw(s, X, Y) {
        cur.stocks.forEach((p) => {
          const g = el("g", {});
          const isQ = q.has(p.name), isB = b.has(p.name);
          g.append(el("title", {}, `${p.name} (${p.sector}) profit ${pct(p.profit)}, risk ${pct(p.risk)}`));
          if (isB) g.append(el("circle", { cx: X(p.risk), cy: Y(p.profit), r: 13, fill: "none", stroke: css("--classic"), "stroke-width": 2.5 }));
          g.append(el("circle", { cx: X(p.risk), cy: Y(p.profit), r: isQ ? 8 : 5.5, fill: isQ ? css("--quantum") : css("--dim"), opacity: isQ || isB ? 1 : 0.75 }));
          if (isQ || isB) g.append(el("text", { x: X(p.risk) + 16, y: Y(p.profit) + 4, class: "lbl" }, p.name));
          s.append(g);
        });
      },
    });
  }

  function drawPortfolios(svg) {
    const marks = [cur.brute, cur.qaoa];
    scatter(svg, cur.cloud, {
      extra: marks,
      draw(s, X, Y) {
        cur.cloud.forEach((p) => s.append(el("circle", { cx: X(p.risk), cy: Y(p.profit), r: 3, fill: css("--dim"), opacity: 0.45 })));
        const b = cur.brute, q = cur.qaoa;
        const d = 9, bx = X(b.risk), by = Y(b.profit);
        s.append(el("path", { d: `M${bx} ${by - d}L${bx + d} ${by}L${bx} ${by + d}L${bx - d} ${by}Z`, fill: "none", stroke: css("--classic"), "stroke-width": 3 }));
        s.append(el("circle", { cx: X(q.risk), cy: Y(q.profit), r: 5.5, fill: css("--quantum") }));
        s.append(el("title", {}, "QAOA vs best classical portfolio"));
      },
    });
  }

  function render() {
    $("chart-title").textContent = view === "stocks"
      ? `Risk against profit for ${cur.n} stocks`
      : `Risk against profit for ${cur.cloud.length} random ${cur.k}-stock portfolios`;
    (view === "stocks" ? drawStocks : drawPortfolios)($("chart"));
    $("legend").innerHTML = view === "stocks"
      ? `<span><i style="background:var(--quantum)"></i>picked by QAOA</span><span><i style="border:2.5px solid var(--classic)"></i>best answer by exhaustive search</span><span><i style="background:var(--dim)"></i>not picked</span>`
      : `<span><i style="background:var(--dim)"></i>random valid portfolios</span><span><i class="dia" style="border:3px solid var(--classic)"></i>best possible (exhaustive)</span><span><i style="background:var(--quantum)"></i>QAOA pick</span>`;

    const q = cur.qaoa, b = cur.brute, bset = new Set(b.picked);
    const chips = (list, cls) => list.map((s) => `<span class="chip ${cls}">${s}</span>`).join("");
    const exact = q.is_optimal;
    $("verdict").innerHTML = `
      <h2>${cur.n} stocks → pick ${cur.k}</h2>
      <span class="badge ${exact ? "ok" : "near"}">${exact ? "QAOA found the best portfolio" : `QAOA found the #${q.rank} best of ${cur.n_feasible.toLocaleString()}`}</span>
      <dl class="picks">
        <dt>QAOA picked</dt><dd>${chips(q.picked, "q")}</dd>
        <dt>Best possible</dt><dd>${chips(b.picked, "c")}</dd>
        <dt>Shared stocks</dt><dd>${q.overlap} of ${cur.k}</dd>
      </dl>
      <table class="kv">
        <tr><td>Profit: QAOA / best</td><td>${pct(q.profit)} / ${pct(b.profit)}</td></tr>
        <tr><td>Risk: QAOA / best</td><td>${pct(q.risk)} / ${pct(b.risk)}</td></tr>
        <tr><td>Possible portfolios</td><td>${cur.n_states.toLocaleString()}</td></tr>
        <tr><td>Chance one shot is optimal</td><td>${pp(q.prob_optimal)} (random ${pp(q.random_prob_optimal)})</td></tr>
        <tr><td>Simulator</td><td>${q.engine === "qiskit" ? "Qiskit Statevector" : "NumPy statevector"}</td></tr>
      </table>`;
  }

  // ---------- scaling chart + table ----------
  function drawScale() {
    const s = $("scale"); s.innerHTML = "";
    const W = 520, H = 260, m = { l: 48, r: 34, t: 12, b: 40 };
    const ns = R.sizes.map((d) => d.n);
    const X = (i) => m.l + (i / (ns.length - 1 || 1)) * (W - m.l - m.r);
    const lo = 0.8, hi = 1.0, Y = (v) => H - m.b - ((v - lo) / (hi - lo)) * (H - m.t - m.b);
    for (let v = lo; v <= hi + 1e-9; v += 0.05) {
      s.append(el("line", { x1: m.l, x2: W - m.r, y1: Y(v), y2: Y(v), stroke: css("--grid") }));
      s.append(el("text", { x: m.l - 6, y: Y(v) + 4, "text-anchor": "end" }, v.toFixed(2)));
    }
    ns.forEach((n, i) => s.append(el("text", { x: X(i), y: H - m.b + 18, "text-anchor": "middle" }, n)));
    s.append(el("text", { x: (W + m.l) / 2, y: H - 4, "text-anchor": "middle" }, "Number of stocks"));
    s.append(el("text", { x: 12, y: H / 2, "text-anchor": "middle", transform: `rotate(-90 12 ${H / 2})` }, "Approximation ratio (1 = perfect)"));
    const line = (key, color, dash) => {
      const d = R.sizes.map((r, i) => `${i ? "L" : "M"}${X(i)} ${Y(r.qaoa[key])}`).join("");
      s.append(el("path", { d, fill: "none", stroke: color, "stroke-width": 2.5, "stroke-dasharray": dash || "" }));
      R.sizes.forEach((r, i) => s.append(el("circle", { cx: X(i), cy: Y(r.qaoa[key]), r: 4.5, fill: color })));
    };
    line("random_approx_ratio", css("--dim"), "6 5");
    line("approx_ratio", css("--quantum"));
    $("scale-legend").innerHTML = `<span><i style="background:var(--quantum)"></i>QAOA</span><span><i style="background:var(--dim)"></i>random guessing</span>`;
  }

  function drawTable() {
    const rows = R.sizes.map((r) => `<tr><td>${r.n}</td><td>${r.n_states.toLocaleString()}</td>
      <td>${r.qaoa.is_optimal ? "yes" : "no (#" + r.qaoa.rank + ")"}</td><td>${r.qaoa.approx_ratio.toFixed(3)}</td>
      <td>${pp(r.qaoa.prob_optimal)}</td><td>${r.qaoa.time_s.toFixed(1)} s</td><td>${r.brute.time_s.toFixed(2)} s</td></tr>`).join("");
    $("table").innerHTML = `<thead><tr><th>Stocks</th><th>Portfolios</th><th>Found best?</th><th>Appr. ratio</th><th>Best per shot</th><th>QAOA time</th><th>Search time</th></tr></thead><tbody>${rows}</tbody>`;
  }

  // ---------- controls ----------
  function setup() {
    const box = $("sizes");
    R.sizes.forEach((r, i) => {
      const b = document.createElement("button");
      b.setAttribute("role", "radio"); b.setAttribute("aria-checked", i === 0); b.textContent = r.n;
      b.onclick = () => { cur = r; [...box.children].forEach((c) => c.setAttribute("aria-checked", c === b)); render(); };
      box.append(b);
    });
    document.querySelectorAll("#views button").forEach((b) => {
      b.onclick = () => { view = b.dataset.view; document.querySelectorAll("#views button").forEach((c) => c.setAttribute("aria-checked", c === b)); render(); };
    });
    drawScale(); drawTable(); render();
    matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => { drawScale(); render(); });
  }
  setup();
})();
